const rows = $input.all().map(item => item.json);

const inconsistent = rows.filter(
    row => row.has_inconsistency === true
);

const consistent = rows.filter(
    row => row.has_inconsistency === false
);

return [
    {
        json: {
            review_type: "reconciliation_audit",
            checked_records: rows.length,
            consistent_records: consistent.length,
            inconsistent_records: inconsistent.length,
            status: inconsistent.length > 0
                ? "INCONSISTENCIES_FOUND"
                : "ALL_CONSISTENT",

            inconsistencies: inconsistent.map(row => ({
                flight_id: row.flight_id,
                seat_class: row.seat_class,
                total_seats: row.total_seats,
                available_seats: row.available_seats,
                calculated_booked: row.calculated_booked,
                actual_bookings: row.booking_count,
                difference:
                    row.calculated_booked - row.booking_count
            })),

            checked_at: new Date().toISOString()
        }
    }
];
